INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q18469222', 'Portuguese campaigns of pacification and occupation', 'The Portuguese campaigns of pacification and occupation (Portuguese: Campanhas de pacificação e ocupação) were a vast set of military operations, conducted by the Portuguese Armed Forces in the overseas provinces of the Portuguese Empire, between 1838 and 1936. Action was seen at Chaimite, in Mozambique, where Mouzinho de Albuquerque captured the Vatua king Gungunhana but also at Môngua, in Angola.', 1880, NULL, NULL, 1920, NULL, NULL, 'decade', '1880s – 1920s', 30, 'https://en.wikipedia.org/wiki/Portuguese_campaigns_of_pacification_and_occupation'),
  ('Q969625', 'Battle of Coolela', 'The Battle of Coolela (Batalha de Coolela in Portuguese) was fought on 7 November 1895 between Portuguese forces commanded by Colonel Eduardo Galhardo and forces of the Gaza Empire commanded by Emperor Gungunhana. The clash took place in the context of the Portuguese Campaigns of Pacification and Occupation in Mozambique, a struggle aimed at resisting Portuguese occupation, and took place in the vicinity of the Coolela swamp, in the district of Manjacaze, province of Gaza.', 1895, 11, 7, NULL, NULL, NULL, 'day', '7 November 1895', 34, 'https://en.wikipedia.org/wiki/Battle_of_Coolela'),
  ('Q609836', 'Portuguese Colonial War', 'The Portuguese Colonial War (Portuguese: Guerra Colonial Portuguesa), also known in Portugal as the Overseas War (Guerra do Ultramar) or in the former colonies as the War of Liberation (Guerra de Libertação), and also known as the Angolan, Guinea-Bissau and Mozambican Wars of Independence, was a 13-year-long conflict fought between Portugal''s military and the emerging nationalist movements in Portugal''s African colonies between 1961 and 1974. The Portuguese regime at the time, the Estado Novo, was overthrown by a military coup in 1974, and the change in government brought the conflict to an…', 1961, 2, 4, 1974, 4, 25, 'day', '4 February 1961 – 25 April 1974', 69, 'https://en.wikipedia.org/wiki/Portuguese_Colonial_War'),
  ('Q51750785', 'Wiriyamu Massacre', 'The Wiriyamu Massacre or Operation Marosca was a Portuguese military action that took place in the province of Tete, Mozambique. It gained a lot of attention internationally after a supposed massacre of the civilian population took place in Wiriyamu.', 1972, 12, NULL, NULL, NULL, NULL, 'month', 'December 1972', 45, 'https://en.wikipedia.org/wiki/Wiriyamu_Massacre'),
  ('Q657661', 'Mozambican Civil War', 'The Mozambican Civil War (Portuguese: Guerra Civil Moçambicana) was a civil war fought in Mozambique from 1977 to 1992 due to a combination of local strife and the polarizing effects of Cold War politics. The fighting was between Mozambique''s ruling Marxist Front for the Liberation of Mozambique (FRELIMO), the anti-communist insurgent forces of the Mozambican National Resistance (RENAMO), and a number of smaller factions such as the PRM, UNAMO, COREMO, UNIPOMO, and FUMO. RENAMO opposed FRELIMO''s attempts to establish a socialist one-party state, and was heavily backed by the anti-communist…', 1977, 5, 30, 1992, 10, 4, 'day', '30 May 1977 – 4 October 1992', 67, 'https://en.wikipedia.org/wiki/Mozambican_Civil_War'),
  ('Q859770', '2000 Mozambique flood', 'The 2000 Mozambique flood was a natural disaster that occurred in February and March 2000. The catastrophic flooding was caused by heavy rainfall caused by Cyclone Leon-Eline that lasted for four weeks and made many homeless.', 2000, 2, NULL, 2000, 3, NULL, 'month', 'February 2000 – March 2000', 57, 'https://en.wikipedia.org/wiki/2000_Mozambique_flood'),
  ('Q3643277', '2007 Mozambican flood', 'The 2007 Mozambican flood began in late December 2006 when the Cahora Bassa Dam overflowed from heavy rains on Southern Africa. It worsened on February 22, 2007, when the Category 4 Cyclone Favio made landfall on the central province of Inhambane; experts tracking the cyclone predicted that it would worsen flooding in the Zambezi River valley.', 2007, 2, 22, NULL, NULL, NULL, 'day', '22 February 2007', 45, 'https://en.wikipedia.org/wiki/2007_Mozambican_flood'),
  ('Q17332331', 'RENAMO insurgency', 'The RENAMO insurgency was a guerrilla campaign by militants of the RENAMO party and one of its splinter factions in Mozambique. The insurgency was widely considered to be an aftershock of the Mozambican Civil War; it resulted in renewed tensions between RENAMO and Mozambique''s ruling FRELIMO coalition over charges of state corruption and the disputed results of the 2014 general elections.', 2014, 9, NULL, NULL, NULL, NULL, 'month', 'September 2014', 34, 'https://en.wikipedia.org/wiki/RENAMO_insurgency_(2013%E2%80%932021)'),
  ('Q18890069', '2015 Southeast Africa floods', 'The 2015 Southeast Africa floods, partially related to Cyclone Bansi and Tropical Storm Chedza, killed at least 176 people in Malawi, 86 in Mozambique, and at least 46 in Madagascar over the course of a week while leaving hundreds more missing. Vice President of Malawi Saulos Chilima stated that over 200,000 Malawian people have been displaced by the flood.', 2015, NULL, NULL, NULL, NULL, NULL, 'year', '2015', 43, 'https://en.wikipedia.org/wiki/2015_Southeast_Africa_floods'),
  ('Q47499139', 'Islamist insurgency in Mozambique', 'The insurgency in Cabo Delgado is an ongoing Islamist insurgency in Cabo Delgado Province, Mozambique, mainly fought between militant Islamists and jihadists attempting to establish an Islamic state in the region, and Mozambican security forces. Civilians have been the main targets of terrorist attacks by Islamist militants.', 2017, 10, 5, NULL, NULL, NULL, 'day', '5 October 2017', 60, 'https://en.wikipedia.org/wiki/Insurgency_in_Cabo_Delgado'),
  ('Q118316106', '2023 Africa floods', 'From February to late-December 2023, floods killed over 2,600 people in 15 countries across Africa.', 2023, 2, 5, NULL, NULL, NULL, 'day', '5 February 2023', 43, 'https://en.wikipedia.org/wiki/2023_Africa_floods');

